    QRView,
    SubcribersList
  },
  data() {
    return {
      SnackBarComponent: {},
      toggle_exclusive: "broadcast_publishmessage",
      broadcast_view: false,
      broadcast_info: {},
      publishDialog: false,
      // brodcastListview: false,
      delete_broadcast: false,
      edit_broadcast: false,
      headers: [{
        text: "Name",
        value: "team_name",
