    async fetch_broadcast() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_broadcast_channels, {
          input: {
            user_email_id: this.$store.getters.GetUserObj.user.user_email_id
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var dataArray = [];
        var response = result.data.list_broadcast_channels;
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
        } else {
          // this.SnackBarComponent = {
          //   SnackbarVmodel: true,
          //   SnackbarColor: "red",
          //   SnackbarText: response.Message,
          //   timeout: 5000,
          //   Top: true,
          // };
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // view_subcribers_list(label, item) {
